input.content:
import { analyze } from './text.mjs';

const textarea = document.getElementById('text');
const countBtn = document.getElementById('count');
const clearBtn = document.getElementById('clear');
const result = document.getElementById('result');

countBtn.addEventListener('click', () => {
  const { chars, words } = analyze(textarea.value);
  result.textContent = `字符: ${chars}  单词: ${words}`;
});

clearBtn.addEventListener('click', () => {
  textarea.value = '';
  result.textContent = '';
});

export function analyze(text) {
  const chars = [...text].filter((c) => !/\s/.test(c)).length;
  const words = text.split(/\s+/).filter(Boolean).length;
  return { chars, words };
}

import { describe, it } from 'node:test';
import { equal } from 'node:assert/strict';
import { analyze } from './text.mjs';

describe('analyze', () => {
  it('one two ab c → 字符9, 单词4, 空白0', () => {
    const r = analyze('one two ab c');
    equal(r.chars, 9);
    equal(r.words, 4);
    equal(r.blanks, 0);
  });

  it('空白字符串 → 字符0, 单词0', () => {
    const r = analyze('   ');
    equal(r.chars, 0);
    equal(r.words, 0);
  });

  it('中文 → 字符按字计, 单词1', () => {
    const r = analyze('你好世界');
    equal(r.chars, 4);
    equal(r.words, 1);
  });
});

